public class CategoryPlot_removeDomainMarker_TriageGen1Test {

    private CategoryPlot plot;
    private Marker mockMarker;

    @Before
    public void setUp() throws Exception {
        plot = new CategoryPlot();
        mockMarker = mock(Marker.class);
    }

    /**
     * Helper method to inject markers into the private maps of CategoryPlot via reflection,
     * since the provided API does not show a direct way to add markers for testing.
     */
    @SuppressWarnings("unchecked")
    private void injectMarker(int index, Marker marker, Layer layer) throws Exception {
        String fieldName = (layer == Layer.FOREGROUND) ? "foregroundDomainMarkers" : "backgroundDomainMarkers";
        Field field = CategoryPlot.class.getDeclaredField(fieldName);
        field.setAccessible(true);
        Map<Integer, ArrayList<Marker>> markersMap = (Map<Integer, ArrayList<Marker>>) field.get(plot);

        if (!markersMap.containsKey(index)) {
            markersMap.put(index, new ArrayList<>());
        }
        markersMap.get(index).add(marker);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Success_WithNotify() throws Exception {
        int index = 0;
        injectMarker(index, mockMarker, Layer.FOREGROUND);

        // Note: fireChangeEvent() is protected/internal, we verify return value.
        // If fireChangeEvent triggers a listener, we would mock the listener.
        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.FOREGROUND, true);

        assertTrue("Marker should be removed successfully", result);
    }

    @Test
    public void testRemoveDomainMarker_Foreground_Failure() throws Exception {
        int index = 0;
        Marker differentMarker = mock(Marker.class);
        injectMarker(index, mockMarker, Layer.FOREGROUND);

        boolean result = plot.removeDomainMarker(index, differentMarker, Layer.FOREGROUND, true);

        assertFalse("Should return false when marker is not found", result);
    }

    @Test
    public void testRemoveDomainMarker_Background_Success_NoNotify() throws Exception {
        int index = 0;
        injectMarker(index, mockMarker, Layer.BACKGROUND);

        boolean result = plot.removeDomainMarker(index, mockMarker, Layer.BACKGROUND, false);

        assertTrue("Marker should be removed successfully from background", result);
    }

    @Test
    public void testRemoveDomainMarker_Background_Failure() throws Exception {
        int index = 5;
        Marker differentMarker = mock(Marker.class);
        injectMarker(index, mockMarker, Layer.BACKGROUND);

        boolean result = plot.removeDomainMarker(index, differentMarker, Layer.BACKGROUND, true);

        assertFalse("Should return false when marker is not found in background", result);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveDomainMarker_InvalidIndex_Foreground() throws Exception {
        // Testing the behavior when index does not exist in the map
        plot.removeDomainMarker(99, mockMarker, Layer.FOREGROUND, true);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testRemoveDomainMarker_InvalidIndex_Background() throws Exception {
        plot.removeDomainMarker(99, mockMarker, Layer.BACKGROUND, true);
    }
}
